import { build } from "esbuild"
import { spawnSync } from "node:child_process"
import { mkdtemp, mkdir, readFile, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..")
const entry = join(root, "native-macos/ParserBundle/CodeMirrorParserEntry.js")
const committed = join(
  root, "native-macos/Sources/LumenEditorApp/Resources/CodeMirrorParserBundle.js"
)
const checking = process.argv.includes("--check")
const generator = join(root, "scripts/generate-native-legacy-language-registry.mjs")
const generatedRegistry = join(
  root, "native-macos/ParserBundle/LegacyLanguageRegistry.generated.js"
)
const temporary = checking ? await mkdtemp(join(tmpdir(), "lumen-parser-")) : null
const output = temporary ? join(temporary, "CodeMirrorParserBundle.js") : committed

try {
  const generation = spawnSync(
    process.execPath, [generator, ...(checking ? ["--check"] : [])],
    { cwd: root, encoding: "utf8" }
  )
  if (generation.stdout) process.stdout.write(generation.stdout)
  if (generation.stderr) process.stderr.write(generation.stderr)
  if (generation.status !== 0) {
    throw new Error(
      `Legacy language registry generation failed with status ${generation.status}`
    )
  }
  await readFile(generatedRegistry)
  await mkdir(dirname(output), { recursive: true })
  const buildResult = await build({
    entryPoints: [entry], outfile: output, bundle: true, format: "iife",
    platform: "browser", target: ["safari17"], charset: "utf8",
    minify: true, sourcemap: false, legalComments: "eof", logLevel: "warning",
    metafile: true,
    banner: {
      js: "/* Generated by build-native-parser-bundle.mjs. Bundled CodeMirror/Lezer packages are MIT licensed; see package-lock.json. */"
    }
  })
  const generated = await readFile(output)
  if (generated.length === 0 || generated.length > 8 * 1024 * 1024) {
    throw new Error(`Native parser bundle has invalid size: ${generated.length} bytes`)
  }
  if (generated.length > Math.floor(1.7 * 1024 * 1024)) {
    throw new Error(
      `Native parser bundle exceeds its 1.7 MiB regression budget: ${generated.length} bytes`
    )
  }
  const externalImports = Object.values(buildResult.metafile.outputs)
    .flatMap(metadata => metadata.imports)
    .filter(item => item.external)
  if (externalImports.length !== 0) {
    throw new Error(
      `Native parser bundle contains external runtime imports: ${
        externalImports.map(item => item.path).join(", ")
      }`
    )
  }
  const dynamicImports = Object.entries(buildResult.metafile.inputs)
    .flatMap(([input, metadata]) => metadata.imports
      .filter(item => item.kind === "dynamic-import")
      .map(item => `${input}: ${item.path}`))
  if (dynamicImports.length !== 0) {
    throw new Error(
      `Native parser bundle source contains dynamic imports: ${dynamicImports.join(", ")}`
    )
  }
  if (checking) {
    const expected = await readFile(committed)
    if (!generated.equals(expected)) {
      throw new Error("Native parser bundle is stale; run npm run build:native-parser")
    }
    process.stdout.write(`Native parser bundle is current (${generated.length} bytes).\n`)
  } else {
    process.stdout.write(`Built ${output} (${generated.length} bytes).\n`)
  }
} finally {
  if (temporary) await rm(temporary, { recursive: true, force: true })
}
